SKILL_PROMOTE_KEY = "AGENTWARE_SKILL_PROMOTE"
SKILL_PROMOTE_DEFAULT = "propose"
_SKILL_PROMOTE_OFF_TOKENS = ("off", "0", "no", "false", "disable", "disabled")
_SKILL_PROMOTE_ON_TOKENS = ("propose", "on", "1", "yes", "true", "enable",
                            "enabled")
