SKILL_PROMOTE_CAP_KEY = "AGENTWARE_SKILL_PROMOTE_CAP"
SKILL_PROMOTE_CAP_DEFAULT = 2
# Tunable detection thresholds (env -> config.env -> the algorithm defaults in
